function esc(s){return String(s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");}
function metadata(title,description,url,image,type){
  const props=[["og:type","website"],["og:site_name","Jerome Griffin"],["og:url",url],["og:title",title],["og:description",description],["og:image",image],["og:image:type",type],["og:image:width","1200"],["og:image:height","630"]];
  let result='<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description)+'"><link rel="canonical" href="'+url+'">';
  for(const [name,value] of props)result+='<meta property="'+name+'" content="'+esc(value)+'">';
  result+='<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'+esc(title)+'"><meta name="twitter:description" content="'+esc(description)+'"><meta name="twitter:image" content="'+image+'">';
  return result;
}
