async function brandPng(){
 const w=1200,h=630,stride=w*3+1,raw=new Uint8Array(stride*h);
 for(let y=0;y<h;y++){let i=y*stride+1;for(let x=0;x<w;x++){raw[i++]=8+Math.round(x*13/w);raw[i++]=21+Math.round(y*17/h);raw[i++]=36+Math.round(x*20/w);}}
 function fill(x0,y0,x1,y1,r,g,b){for(let y=Math.max(0,y0);y<Math.min(h,y1);y++){let i=y*stride+1+Math.max(0,x0)*3;for(let x=Math.max(0,x0);x<Math.min(w,x1);x++){raw[i++]=r;raw[i++]=g;raw[i++]=b;}}}
 fill(40,35,1160,41,205,171,106);fill(40,586,1160,592,205,171,106);
 fill(40,35,46,592,205,171,106);fill(1154,35,1160,592,205,171,106);
 function words(str,x,y,scale,color){for(const ch of str){const pat=glyph[ch]||glyph[" "];for(let yy=0;yy<7;yy++)for(let xx=0;xx<5;xx++)if(pat[yy][xx]==="1")fill(x+xx*scale,y+yy*scale,x+(xx+1)*scale,y+(yy+1)*scale,...color);x+=6*scale;}}
 words("JEROME",190,130,20,[238,206,146]);words("GRIFFIN",101,315,20,[238,206,146]);words("APPS & GAMES",222,514,9,[195,207,216]);
 const cs=new CompressionStream("deflate"),writer=cs.writable.getWriter();
 const read=new Response(cs.readable).arrayBuffer();
 const write=writer.write(raw).then(()=>writer.close());
 const zipped=new Uint8Array(await read);await write;
 function crc(a){let c=0xffffffff;for(let i=0;i<a.length;i++){c^=a[i];for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}
 function chunk(t,data){const b=new Uint8Array(12+data.length),v=new DataView(b.buffer);v.setUint32(0,data.length);for(let j=0;j<4;j++)b[4+j]=t.charCodeAt(j);b.set(data,8);v.setUint32(8+data.length,crc(b.subarray(4,8+data.length)));return b;}
 const info=new Uint8Array(13);new DataView(info.buffer).setUint32(0,w);new DataView(info.buffer).setUint32(4,h);info[8]=8;info[9]=2;
 const parts=[new Uint8Array([137,80,78,71,13,10,26,10]),chunk("IHDR",info),chunk("IDAT",zipped),chunk("IEND",new Uint8Array())];
 const out=new Uint8Array(parts.reduce((n,a)=>n+a.length,0));let offset=0;for(const part of parts){out.set(part,offset);offset+=part.length;}return out;
}
let rookBytes,brandPromise;
function rooksJpg(){if(!rookBytes){const s=atob(jpgBase64);rookBytes=Uint8Array.from(s,x=>x.charCodeAt(0));}return rookBytes;}
addEventListener("fetch",e=>e.respondWith((async()=>{
 const req=e.request,url=new URL(req.url),path=url.pathname,isHead=req.method==="HEAD";
 if(!["GET","HEAD"].includes(req.method))return new Response("Method Not Allowed",{status:405});
 if(url.hostname==="www.jeromegriffin.com")return Response.redirect(root+path+url.search,308);
 if(path==="/images/rooks-v1.jpg")return new Response(isHead?null:rooksJpg(),{headers:{"content-type":"image/jpeg","cache-control":"public,max-age=86400"}});
 if(path==="/images/jerome-griffin-v1.png"){if(!brandPromise)brandPromise=brandPng();return new Response(isHead?null:await brandPromise,{headers:{"content-type":"image/png","cache-control":"public,max-age=86400"}});}
 let html;
 if(url.hostname==="apps.jeromegriffin.com")html=apps();
 else if(path==="/"||path==="/index.html")html=home();
 else if(path==="/rooks"||path==="/rooks/")html=rooks();
 else if(/^\/R\/(?:[A-Z]{3}[0-9]{2,4}|[23456789ABCDEFGHJKLMNPQRSTUVWXYZ]{8})\/?$/.test(path.toUpperCase()))html=roomInvite(path.split("/")[2].toUpperCase());
 else if(path==="/apps"||path==="/apps/")html=apps();
 else return new Response("Not Found",{status:404});
 return new Response(isHead?null:html,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"public,max-age=120","x-content-type-options":"nosniff"}});
})()));
